package com.dudoziworkshop.dzlog.data.backup

import com.dudoziworkshop.dzlog.data.platform.backupSha256
import com.dudoziworkshop.dzlog.domain.model.*
import kotlin.test.*

class BackupMigrationContractTest {
    @Test fun fixedAndroidSchemaOneArchiveRoundTripsSupportedFieldsOnBothPlatforms() {
        val archive = LocalTemplateBackupCodec.decode(fixedArchive)
        val original = archive.templates.single()
        assertEquals("fixture-template", archive.activeTemplateId)
        assertEquals(1792422299000L, archive.createdAtMillis)
        assertEquals(TableCellDataType.entries, original.templateState.cells.map { it.dataType })
        assertEquals(CellValue.CounterSeed(47), original.templateState.cells[4].typedValue)
        assertEquals(1, original.templateState.cells[5].phraseCompletedShots)
        assertEquals(5, original.templateState.pathSlotDrafts.size)
        assertNull(original.templateState.pathSlotDrafts[2])
        val decoded = LocalTemplateBackupCodec.decode(LocalTemplateBackupCodec.encode(listOf(original), original.id, archive.createdAtMillis))
        val expected = original.copy(templateState = original.templateState.copy(cells = original.templateState.cells.map {
            if (it.dataType == TableCellDataType.COUNTER) it.copy(typedValue = CellValue.CounterSeed(1)) else it
        }))
        assertEquals(listOf(expected), decoded.templates)
        assertEquals(original.id, decoded.activeTemplateId)
        assertEquals(CellValue.CounterSeed(47), original.templateState.cells[4].typedValue)
    }

    @Test fun sha256UsesUtf8AndKnownVectors() {
        assertEquals("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", backupSha256(""))
        assertEquals("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", backupSha256("abc"))
        assertEquals("0c8a6676b397adf41159dfd5bcd74e8206f7d38ddeffff44c8be737e2b502a38", backupSha256("한글 🌱"))
    }

    @Test fun archiveIntegerTypeAndExactChecksumStayStrict() {
        assertFailsWith<IllegalArgumentException> { LocalTemplateBackupCodec.decode(fixedArchive.replace("\"schemaVersion\": 1,", "\"schemaVersion\": 1.0,")) }
        assertFailsWith<IllegalArgumentException> { LocalTemplateBackupCodec.decode(fixedArchive.replace("c8da109a9ab8a9fb924837b9de3d345aad81dac506dd88a5b7049851f06d74c6", "0".repeat(64))) }
    }
}

